# Capture multinomial imputation convergence without changing fitting settings.
trace('multinom',where=asNamespace('nnet'),exit=quote({rv<-returnValue();neutro_cat('MULTINOM_CONVERGENCE',rv$convergence,'\n');if(!is.null(rv$convergence)&&rv$convergence!=0)stop(paste('polyreg multinom nonconvergence code',rv$convergence))}),print=FALSE)
run_scheme<-function(name,aa,mm,pp,nnet_limit){csv(data.frame(target=rownames(pp),pp,check.names=FALSE),paste0(name,'_predictor_matrix.csv'));events<-data.frame();ww<-character();err<-NULL
 check_events<-function(){for(env in sys.frames())if(exists('loggedEvents',envir=env,inherits=FALSE)){ev<-get('loggedEvents',envir=env,inherits=FALSE);if(!is.null(ev)&&nrow(ev)>0&&any(nzchar(as.character(ev$out)))){events<<-ev;stop('mice internal prediction removal/collinearity/ridge event')}}}
 assign('check_events',check_events,envir=.GlobalEnv);post<-setNames(rep('',ncol(aa)),names(aa));post[mm!='']<-'check_events()'
 neutro_cat('SCHEME_START',name,'\n');imp<-tryCatch(withCallingHandlers(mice(aa,m=20,maxit=20,method=mm,predictorMatrix=pp,seed=20261008,donors=5,post=post,nnet.maxit=nnet_limit,polr.to.loggedEvents=TRUE,printFlag=TRUE),warning=function(w){ww<<-c(ww,conditionMessage(w));stop(paste('imputation warning:',conditionMessage(w)))}),error=function(e){err<<-conditionMessage(e);NULL})
 if(!is.null(imp)){if(!is.null(imp$loggedEvents))events<-imp$loggedEvents;if(any(nzchar(as.character(events$out))))err<-'logged events after completion';if(!isTRUE(all.equal(unname(imp$predictorMatrix),unname(pp),check.attributes=FALSE)))err<-'predictor matrix changed';if(anyNA(complete(imp,1)[,names(mm)[mm!='']]))err<-'missing values remain'}
 csv(events,paste0(name,'_events.csv'));csv(data.frame(warning=ww),paste0(name,'_warnings.csv'));usable<-!is.null(imp)&&is.null(err);neutro_cat('SCHEME_END',name,'usable=',usable,'reason=',if(is.null(err))''else err,'\n');list(imp=imp,usable=usable,reason=if(is.null(err))''else err)}

# Select solely on imputation diagnostics before any analysis models.
make_pred<-function(aa,mm,design){pp<-matrix(0L,ncol(aa),ncol(aa),dimnames=list(names(aa),names(aa)));pp[mm!='',]<-1;diag(pp)<-0;if(design=='primary')pp[,'SDDSRVYR']<-0;pp}
inverse_data<-function(filled){for(v in intersect(numeric_vars,names(filled)))filled[[v]]<-filled[[v]]*scales[v]+centers[v];if(is.numeric(filled$education))filled$education<-factor(levels(a_original$education)[as.integer(filled$education)],levels=levels(a_original$education)) else filled$education<-factor(as.character(filled$education),levels=levels(a_original$education));filled}
assess<-function(z,label){rows<-data.frame();for(v in names(method)[method!='']){original<-a_original[[v]];num<-function(x)if(is.factor(x))as.numeric(x)else as.numeric(x);obs<-num(original[!is.na(original)]);for(i in 1:20){filled<-inverse_data(complete(z,i));xx<-num(filled[[v]]);mean_diff<-(mean(xx)-mean(obs))/sd(obs);sd_diff<-sd(xx)/sd(obs)-1;chain<-z$chainMean[v,,i];# Normalize chain drift in its own scale; compare first/last halves and slope.
 obs_scale<-if(v%in%numeric_vars)1 else sd(obs);drift<-(mean(tail(chain,10))-mean(head(chain,10)))/obs_scale;trendfit<-lm(chain~seq_along(chain));slope<-coef(trendfit)[2]*19/obs_scale;trendP<-coef(summary(trendfit))[2,4];rows<-rbind(rows,data.frame(variable=v,imputation=i,observed_mean=mean(obs),observed_SD=sd(obs),completed_mean=mean(xx),completed_SD=sd(xx),standardized_mean_difference=mean_diff,relative_SD_difference=sd_diff,chain_half_difference=drift,chain_total_fitted_change=unname(slope),chain_trend_P=trendP))}};rows$chain_trend_P_Holm<-p.adjust(rows$chain_trend_P,method='holm');csv(rows,paste0(label,'_diagnostic_gate.csv'));# Conservative checks on completed-data distributions and material chain drift; no outcome effect consulted.
 acceptable<-all(abs(rows$standardized_mean_difference)<=.1 & abs(rows$relative_SD_difference)<=.1 & !(abs(rows$chain_total_fitted_change)>.1 & rows$chain_trend_P_Holm<.05));list(acceptable=acceptable,reason=if(acceptable)''else 'distribution or chain drift exceeds 0.1 standardized/relative diagnostic tolerance')}
schemes<-data.frame();selected<-NULL
for(plan in c('A','B','C')){for(design_name in c('primary','fallback')){aa<-a;mm<-method;if(plan=='B') {aa$education<-ordered(aa$education,levels=levels(a_original$education));mm['education']<-'polr'};if(plan=='C'){aa$education<-as.numeric(aa$education);mm['education']<-'pmm'};if(design_name=='fallback'){aa<-aa[,!names(aa)%in%c('SDMVSTRA','SDMVPSU')];mm<-mm[names(aa)]};pp<-make_pred(aa,mm,design_name)
 for(limit in if(plan=='C')500 else c(500,1000)){label<-paste(plan,design_name,limit,sep='_');neutro_cat('PLAN_START',label,'\n');trial<-run_scheme(label,aa,mm,pp,limit);if(!trial$usable){schemes<-rbind(schemes,data.frame(plan=plan,design=design_name,nnet_maxit=limit,usable=FALSE,reason=trial$reason));if(!grepl('nonconvergence',trial$reason))break;next};gate<-assess(trial$imp,label);schemes<-rbind(schemes,data.frame(plan=plan,design=design_name,nnet_maxit=limit,usable=gate$acceptable,reason=gate$reason));if(gate$acceptable){imp<-trial$imp;selected<-label;break}else break};if(!is.null(selected))break};if(!is.null(selected))break}
if(is.null(selected)){csv(schemes,'scheme_usability.csv');stop('All specified schemes failed; no analysis models fitted')}
